"""Get a dictionary with all of the fields to filter

    Args:
        fields_to_filter_by (dict): Dictionary with all the fields to filter

    Returns:
        string. Filter to send in the API request
    """
def reformat_filter(fields_to_filter_by: Any) -> object {
    filter_req = '';
    for (field_key, field_value) in fields_to_filter_by.items() {
        if field_value {
            filter_req += f"{field_key}+eq+'{field_value}'&";
        }
    }
    return filter_req;
}

""" Simple way to compress string. """
def simple_compression(string: Any) -> object {
    compressed_string = "";
    (last, n) = ("", 1);
    for cha in string {
        if (cha == last) {
            n += 1;
        } else {
            if (n > 1) {
                compressed_string += str(n);
            }
            compressed_string += cha;
            (last, n) = (cha, 1);
        }
    }
    if (n > 1) {
        compressed_string += str(n);
    }
    return compressed_string;
}

